// Commission deductions use a settlement snapshot so the same advance is never deducted twice.
let advanceContext=null;
function initAdvances(){state.advances??=[];for(const r of Object.values(state.records)){if(r.commissionPaid&&!r.settlement)r.settlement={gross:cents(r.commission),deductions:[],net:cents(r.commission),date:null};}}
function monthAfter(m){const [y,n]=m.split('-').map(Number);return n===12?(y+1)+'-01':y+'-'+String(n+1).padStart(2,'0');}
function advanceUsed(id){return Object.values(state.records).reduce((sum,r)=>sum+(r.settlement?.deductions||[]).filter(d=>d.id===id).reduce((n,d)=>n+d.amount,0),0);}
function commissionSummary(person=selected,month=$('#month').value){initAdvances();const r=state.records[month+':'+person],gross=cents(r?.commission||0);if(r?.settlement){const s=r.settlement;return {...s,discount:s.deductions.reduce((n,d)=>n+d.amount,0),paid:s.net,remaining:0,closed:true};}let available=gross;const deductions=[];for(const a of state.advances.filter(a=>a.person===person&&!a.voided&&a.month<=month).sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id))){const amount=Math.min(available,Math.max(0,a.amount-advanceUsed(a.id)));if(amount>0){deductions.push({id:a.id,amount,description:a.description});available-=amount;}}return {gross,deductions,discount:gross-available,net:available,paid:0,remaining:available,closed:false};}
function settleCommission(){const r=record(),s=commissionSummary();if(s.closed){const later=Object.entries(state.records).some(([key,value])=>key.endsWith(':'+selected)&&key.slice(0,7)>$('#month').value&&value.settlement);if(later){toast('Reabra primeiro as comissões posteriores desta pessoa.');return;}if(!confirm('Reabrir esta comissão? O pagamento será desmarcado e os vales voltarão a ficar disponíveis para desconto.'))return;delete r.settlement;r.commissionPaid=false;}else{if(!s.gross)return;if(!confirm('Confirmar quitação: comissão '+money(s.gross/100)+', descontos '+money(s.discount/100)+' e pagamento líquido de '+money(s.net/100)+'?'))return;r.settlement={gross:s.gross,deductions:s.deductions,net:s.net,date:new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())};r.commissionPaid=true;}save();render();}
function commissionPanel(){const s=commissionSummary();return `<div class="commission-breakdown"><div><small>Comissão bruta</small><strong>${money(s.gross/100)}</strong></div><div><small>Vales descontados</small><strong>− ${money(s.discount/100)}</strong></div><div><small>Líquido a receber</small><strong>${money(s.net/100)}</strong></div><div><small>Já pago em comissão</small><strong>${money(s.paid/100)}</strong></div></div><div class="week-top"><p class="hint">${s.closed?'Comissão quitada. Descontos e pagamento registrados.':'Ainda a pagar: '+money(s.remaining/100)+'. Os descontos são confirmados ao quitar a comissão.'}</p><button class="pay ${s.closed?'paid':''}" id="commission-pay" ${!s.gross?'disabled':''}>${s.closed?'✓ Quitada · reabrir':'Confirmar quitação da comissão'}</button></div>${s.deductions.length?`<details><summary>Ver descontos desta comissão</summary><dl class="ledger">${s.deductions.map(d=>`<div><dt>${esc(d.description)}</dt><dd>${money(d.amount/100)}</dd></div>`).join('')}</dl></details>`:''}`;}
function advancesView(){initAdvances();const list=state.advances.filter(a=>a.person===selected).sort((a,b)=>b.date.localeCompare(a.date));const outstanding=list.filter(a=>!a.voided).reduce((n,a)=>n+Math.max(0,a.amount-advanceUsed(a.id)),0),s=commissionSummary();return `<div class="section-head" style="padding:0"><div><h3>Vales e adiantamentos</h3><p class="hint">Celular, aluguel, empréstimos e outros valores a descontar da comissão.</p></div><button class="primary" id="add-advance">＋ Registrar vale</button></div><div class="balance-summary"><div>Saldo total de vales a descontar<strong>${money(outstanding/100)}</strong></div><div>Desconto ${s.closed?'confirmado':'previsto'} nesta comissão<strong>${money(s.discount/100)}</strong></div></div><p class="hint">Histórico completo desta pessoa. Cada vale tem um mês inicial para desconto. O que exceder a comissão permanece pendente para a próxima. O VT não participa destes descontos.</p>${list.length?list.map(a=>{const used=advanceUsed(a.id),remaining=Math.max(0,a.amount-used);return `<article class="transfer ${a.voided?'voided':''}"><div><strong>${esc(a.description)}</strong><small>Pago em ${esc(a.date.split('-').reverse().join('/'))} · Descontar a partir de ${esc(a.month.split('-').reverse().join('/'))}</small><small>${a.voided?'Cancelado':remaining===0?'Descontado integralmente':used?'Desconto parcial':'Pendente'} · Já descontado: ${money(used/100)} · Saldo: ${money(a.voided?0:remaining/100)}</small></div><div class="transfer-value"><strong>${money(a.amount/100)}</strong><div>${used?'<small>Vinculado a comissão quitada</small>':`<button data-edit-advance="${esc(a.id)}">Editar</button><button data-void-advance="${esc(a.id)}">${a.voided?'Restaurar':'Cancelar'}</button>`}</div></div></article>`;}).join(''):'<div class="empty"><h3>Nenhum vale registrado</h3><p>Registre o valor e a data do que você adiantou à pessoa.</p></div>'}`;}
function openAdvance(id=null){initAdvances();const a=state.advances.find(a=>a.id===id);if(a&&advanceUsed(id)){toast('Reabra a comissão vinculada antes de alterar este vale.');return;}const f=$('#advance-form');f.reset();f.elements.person.innerHTML=state.people.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${esc(p.role||'Prestador')}</option>`).join('');f.elements.person.value=a?.person||selected;let month=$('#month').value;while(state.records[month+':'+selected]?.settlement)month=monthAfter(month);advanceContext={id,person:selected};$('#advance-title').textContent=a?'Editar vale':'Registrar vale';f.elements.description.value=a?.description||'';f.elements.amount.value=a?formatCredit(a.amount):'';f.elements.date.value=a?.date||new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());f.elements.month.value=a?.month||month;$('#advance-dialog').showModal();}
function validateAdvances(s){if(s.advances!==undefined){if(!Array.isArray(s.advances))throw Error('Vales inválidos');const ids=new Set();for(const a of s.advances){if(!a||typeof a.id!=='string'||ids.has(a.id)||!s.people.some(p=>p.id===a.person)||!validDate(a.date)||!/^\d{4}-(0[1-9]|1[0-2])$/.test(a.month)||!Number.isSafeInteger(a.amount)||a.amount<=0||typeof a.description!=='string'||!a.description.trim()||typeof a.voided!=='boolean')throw Error('Vale inválido');ids.add(a.id);}}const used={};for(const [key,r] of Object.entries(s.records)){if(!r.settlement)continue;const x=r.settlement;if(!Number.isSafeInteger(x.gross)||x.gross<0||!Number.isSafeInteger(x.net)||x.net<0||!Array.isArray(x.deductions)||!(x.date===null||validDate(x.date)))throw Error('Quitação inválida');let total=0;for(const d of x.deductions){const a=(s.advances||[]).find(a=>a.id===d.id);if(!a||a.person!==key.slice(8)||a.voided||!Number.isSafeInteger(d.amount)||d.amount<=0||typeof d.description!=='string')throw Error('Desconto inválido');used[d.id]=(used[d.id]||0)+d.amount;if(used[d.id]>a.amount)throw Error('Desconto duplicado');total+=d.amount;}if(x.gross-total!==x.net)throw Error('Total inválido');}}
document.querySelector('#close-advance').onclick=()=>$('#advance-dialog').close();
document.querySelector('#advance-form').onsubmit=e=>{e.preventDefault();const f=e.target;if(!f.reportValidity()||!advanceContext)return;const a={id:advanceContext.id||crypto.randomUUID(),person:f.elements.person.value,description:f.elements.description.value.trim(),amount:parseCredit(f.elements.amount.value),date:f.elements.date.value,month:f.elements.month.value,voided:false};if(!state.people.some(p=>p.id===a.person)||!a.description||!validDate(a.date)||!a.amount)return;if(state.records[a.month+':'+a.person]?.settlement){toast('Essa comissão já está quitada. Escolha um mês em aberto.');return;}const prior=state.advances.find(x=>x.id===a.id);if(prior&&advanceUsed(a.id)){toast('Este vale já foi descontado em uma comissão quitada.');return;}if(prior)Object.assign(prior,a);else state.advances.push(a);selected=a.person;tab='advances';save();render();$('#advance-dialog').close();toast('Vale registrado');};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='add-advance')openAdvance();if(b.dataset.editAdvance)openAdvance(b.dataset.editAdvance);if(b.dataset.voidAdvance){const a=state.advances.find(a=>a.id===b.dataset.voidAdvance);if(!a||advanceUsed(a.id))return;a.voided=!a.voided;save();render();}});

document.querySelector('#advance-form').addEventListener('change',e=>{if(e.target.name!=='person')return;const f=e.currentTarget;let month=f.elements.month.value;if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(month))return;while(state.records[month+':'+f.elements.person.value]?.settlement)month=monthAfter(month);f.elements.month.value=month;});
